Below is the complete implementation of a binary decision tree classifier using CART with Gini impurity, reduced-error pruning, support for continuous and categorical features, and efficient split-finding.

**`/home/kara/decision_tree.py`:**

```python
import numpy as np
from collections import Counter
from itertools import combinations


class DecisionTreeNode:
    """Node in a binary decision tree."""
    __slots__ = ('left', 'right', 'feature_idx', 'threshold', 'value', 'is_leaf')

    def __init__(self, value=None, is_leaf=False):
        self.left = None
        self.right = None
        self.feature_idx = None
        self.threshold = None    # float (continuous) or frozenset (categorical)
        self.value = value       # class prediction for leaf nodes
        self.is_leaf = is_leaf


class DecisionTreeCART:
    """
    Binary decision tree classifier using CART algorithm.

    Parameters
    ----------
    max_depth : int or None
        Maximum tree depth. If None, grow until pure or min_samples_split.
    min_samples_split : int
        Minimum samples required to split a node.
    min_samples_leaf : int
        Minimum samples required in a leaf node.
    cat_features : list of int or None
        Indices of categorical features (0-based).
    """

    def __init__(self, max_depth=None, min_samples_split=2, min_samples_leaf=1,
                 cat_features=None):
        self.max_depth = max_depth
        self.min_samples_split = min_samples_split
        self.min_samples_leaf = min_samples_leaf
        self.cat_features = set(cat_features) if cat_features else set()
        self.tree_ = None
        self.n_classes_ = None
        self.classes_ = None
        self._numeric_cols_ = []

    # ---------- Public API ----------

    def fit(self, X, y):
        """Build the tree from training data."""
        X = np.asarray(X, dtype=object)
        y = np.asarray(y)
        self.classes_ = np.unique(y)
        self.n_classes_ = len(self.classes_)
        # Convert continuous columns to float (they may be strings if mixed types)
        self._numeric_cols_ = []
        for f_idx in range(X.shape[1]):
            if f_idx not in self.cat_features:
                try:
                    X[:, f_idx] = X[:, f_idx].astype(float)
                    self._numeric_cols_.append(f_idx)
                except (ValueError, TypeError):
                    self.cat_features.add(f_idx)
        self.tree_ = self._grow_tree(X, y, depth=0)
        return self

    def predict(self, X):
        """Predict class labels for samples in X."""
        X = np.asarray(X, dtype=object)
        for f_idx in self._numeric_cols_:
            try:
                X[:, f_idx] = X[:, f_idx].astype(float)
            except (ValueError, TypeError):
                pass
        return np.array([self._predict_node(x, self.tree_) for x in X])

    def predict_proba(self, X):
        """Predict class probabilities. Each row sums to 1."""
        X = np.asarray(X, dtype=object)
        for f_idx in self._numeric_cols_:
            try:
                X[:, f_idx] = X[:, f_idx].astype(float)
            except (ValueError, TypeError):
                pass
        results = []
        for x in X:
            dist = self._get_leaf_distribution(x, self.tree_)
            total = sum(dist.values())
            probs = np.zeros(self.n_classes_)
            for i, cls in enumerate(self.classes_):
                probs[i] = dist.get(cls, 0) / total if total > 0 else 0
            results.append(probs)
        return np.array(results)

    def prune(self, X_val, y_val):
        """
        Reduced-error pruning using held-out validation set.
        Post-order traversal: replace a subtree with a majority-class leaf
        if validation error does NOT increase.
        """
        X_val = np.asarray(X_val, dtype=object)
        y_val = np.asarray(y_val)
        for f_idx in self._numeric_cols_:
            try:
                X_val[:, f_idx] = X_val[:, f_idx].astype(float)
            except (ValueError, TypeError):
                pass
        if len(y_val) == 0:
            return
        baseline_preds = self.predict(X_val)
        baseline_accuracy = np.mean(baseline_preds == y_val)
        self._prune_node(self.tree_, X_val, y_val, baseline_accuracy)

    def get_depth(self):
        return self._get_depth(self.tree_)

    def get_num_nodes(self):
        return self._get_num_nodes(self.tree_)

    # ---------- Impurity ----------

    def _gini(self, y):
        if len(y) == 0:
            return 0.0
        _, counts = np.unique(y, return_counts=True)
        probs = counts / len(y)
        return 1.0 - np.sum(probs ** 2)

    def _gini_split(self, y_left, y_right):
        n = len(y_left) + len(y_right)
        if n == 0:
            return 0.0
        w_left = len(y_left) / n
        w_right = len(y_right) / n
        return w_left * self._gini(y_left) + w_right * self._gini(y_right)

    # ---------- Split Finding ----------

    def _best_split_continuous(self, X_col, y):
        """Try all midpoints between consecutive distinct values for a continuous feature."""
        # Ensure numeric
        if X_col.dtype == object or X_col.dtype.kind in ('U', 'S'):
            try:
                X_col = X_col.astype(float)
            except (ValueError, TypeError):
                return None, float('inf')

        indices = np.argsort(X_col)
        sorted_x = X_col[indices]
        sorted_y = y[indices]

        best_gini = float('inf')
        best_threshold = None

        for i in range(len(sorted_x) - 1):
            if sorted_x[i] == sorted_x[i + 1]:
                continue
            threshold = (sorted_x[i] + sorted_x[i + 1]) / 2.0

            n_left = i + 1
            n_right = len(sorted_x) - n_left
            if n_left < self.min_samples_leaf or n_right < self.min_samples_leaf:
                continue

            y_left = sorted_y[:i + 1]
            y_right = sorted_y[i + 1:]
            gini = self._gini_split(y_left, y_right)
            if gini < best_gini:
                best_gini = gini
                best_threshold = threshold

        return best_threshold, best_gini

    def _best_split_categorical(self, X_col, y):
        """
        Find best binary split for a categorical feature.
        - If K ≤ 10 categories: try all 2^(K-1)-1 non-empty proper subsets.
        - If K > 10 categories: order by class probability and try splits
          along that ordering (Breiman et al. 1984, ESL Algorithm 9.2).
        """
        unique_vals = np.unique(X_col)
        if len(unique_vals) <= 1:
            return None, float('inf')

        best_gini = float('inf')
        best_subset = None

        if len(unique_vals) <= 10:
            vals_list = list(unique_vals)
            for r in range(1, len(vals_list)):
                for subset in combinations(vals_list, r):
                    subset = frozenset(subset)
                    mask = np.array([v in subset for v in X_col])
                    n_left = np.sum(mask)
                    n_right = len(mask) - n_left
                    if n_left < self.min_samples_leaf or n_right < self.min_samples_leaf:
                        continue
                    gini = self._gini_split(y[mask], y[~mask])
                    if gini < best_gini:
                        best_gini = gini
                        best_subset = subset
        else:
            # Order categories by majority-class proportion
            cat_order = {}
            for val in unique_vals:
                mask = X_col == val
                if np.sum(mask) == 0:
                    continue
                _, counts = np.unique(y[mask], return_counts=True)
                cat_order[val] = np.max(counts) / np.sum(mask)
            sorted_cats = sorted(cat_order, key=cat_order.get)

            for i in range(1, len(sorted_cats)):
                subset = frozenset(sorted_cats[:i])
                mask = np.array([v in subset for v in X_col])
                n_left = np.sum(mask)
                n_right = len(mask) - n_left
                if n_left < self.min_samples_leaf or n_right < self.min_samples_leaf:
                    continue
                gini = self._gini_split(y[mask], y[~mask])
                if gini < best_gini:
                    best_gini = gini
                    best_subset = subset

        return best_subset, best_gini

    def _find_best_split(self, X, y):
        """Find the best feature and split across all features."""
        best_gini = float('inf')
        best_feature = None
        best_threshold = None
        current_gini = self._gini(y)

        for f_idx in range(X.shape[1]):
            X_col = X[:, f_idx]
            if f_idx in self.cat_features:
                threshold, gini = self._best_split_categorical(X_col, y)
            else:
                threshold, gini = self._best_split_continuous(X_col, y)
            if threshold is not None and gini < best_gini:
                best_gini = gini
                best_feature = f_idx
                best_threshold = threshold

        if best_gini >= current_gini:
            return None, None, float('inf')
        return best_feature, best_threshold, best_gini

    # ---------- Tree Growing ----------

    def _majority_class(self, y):
        return Counter(y).most_common(1)[0][0]

    def _grow_tree(self, X, y, depth):
        if len(y) < self.min_samples_split:
            return DecisionTreeNode(value=self._majority_class(y), is_leaf=True)
        if self.max_depth is not None and depth >= self.max_depth:
            return DecisionTreeNode(value=self._majority_class(y), is_leaf=True)
        if len(np.unique(y)) == 1:
            return DecisionTreeNode(value=y[0], is_leaf=True)

        best_feature, best_threshold, _ = self._find_best_split(X, y)
        if best_feature is None:
            return DecisionTreeNode(value=self._majority_class(y), is_leaf=True)

        X_col = X[:, best_feature]
        if best_feature in self.cat_features:
            mask = np.array([v in best_threshold for v in X_col])
        else:
            mask = X_col <= best_threshold

        n_left, n_right = np.sum(mask), len(mask) - np.sum(mask)
        if n_left == 0 or n_right == 0:
            return DecisionTreeNode(value=self._majority_class(y), is_leaf=True)

        node = DecisionTreeNode()
        node.feature_idx = best_feature
        node.threshold = best_threshold
        node.left = self._grow_tree(X[mask], y[mask], depth + 1)
        node.right = self._grow_tree(X[~mask], y[~mask], depth + 1)
        return node

    # ---------- Prediction ----------

    def _predict_node(self, x, node):
        if node.is_leaf:
            return node.value
        x_val = x[node.feature_idx]
        if node.feature_idx in self.cat_features:
            go_left = x_val in node.threshold
        else:
            go_left = x_val <= node.threshold
        return self._predict_node(x, node.left if go_left else node.right)

    def _get_leaf_distribution(self, x, node):
        if node.is_leaf:
            return Counter({node.value: 1})
        x_val = x[node.feature_idx]
        if node.feature_idx in self.cat_features:
            go_left = x_val in node.threshold
        else:
            go_left = x_val <= node.threshold
        return self._get_leaf_distribution(x, node.left if go_left else node.right)

    def _predict_subtree(self, X, node):
        return np.array([self._predict_node(x, node) for x in X])

    # ---------- Reduced-Error Pruning ----------

    def _prune_node(self, node, X_val, y_val, baseline_accuracy):
        """Post-order recursive pruning."""
        if node is None or node.is_leaf:
            return

        X_col = X_val[:, node.feature_idx]
        if node.feature_idx in self.cat_features:
            mask = np.array([v in node.threshold for v in X_col])
        else:
            mask = X_col <= node.threshold

        X_left, y_left = X_val[mask], y_val[mask]
        X_right, y_right = X_val[~mask], y_val[~mask]

        if len(X_left) > 0:
            self._prune_node(node.left, X_left, y_left, baseline_accuracy)
        if len(X_right) > 0:
            self._prune_node(node.right, X_right, y_right, baseline_accuracy)

        if len(y_val) == 0:
            return

        majority = self._majority_class(y_val)
        leaf_accuracy = np.mean(y_val == majority)
        subtree_preds = self._predict_subtree(X_val, node)
        subtree_accuracy = np.mean(subtree_preds == y_val)

        # Prune if leaf accuracy >= subtree accuracy (error does not increase)
        if leaf_accuracy >= subtree_accuracy:
            node.left = None
            node.right = None
            node.is_leaf = True
            node.value = majority
            node.feature_idx = None
            node.threshold = None

    # ---------- Tree Stats ----------

    def _get_depth(self, node):
        if node is None or node.is_leaf:
            return 0
        return 1 + max(self._get_depth(node.left), self._get_depth(node.right))

    def _get_num_nodes(self, node):
        if node is None:
            return 0
        if node.is_leaf:
            return 1
        return 1 + self._get_num_nodes(node.left) + self._get_num_nodes(node.right)
```

### Key Design Decisions

| Concern | Approach |
|---|---|
| **Gini impurity** | `1 - Σ(pᵢ²)`, with weighted average for split candidates |
| **Continuous splits** | Sort values, try all midpoints between distinct consecutive values — O(N log N) per feature |
| **Categorical splits** | ≤10 categories → exhaustive `2^(K-1)-1` subsets; >10 categories → order by class probability, try splits along that ordering (Breiman 1984) |
| **Full tree growth** | Recursive, stops when pure, `min_samples_split`, `min_samples_leaf`, or `max_depth` hit |
| **Reduced-error pruning** | Post-order traversal: test each internal node on validation data; if a majority-class leaf matches or beats the subtree's accuracy, prune |
| **Mixed-type arrays** | `np.asarray(X, dtype=object)` then convert continuous columns to `float`; strings that can't convert become categorical |
| **Efficiency** | Pre-sorting for continuous features; pre-computed baselines; avoid redundant copies |

